begin;
insert into publishers (name) values ('Linear') on conflict (name) do nothing;
insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Linear Asks', 'linear-asks', p.id, 'AI assistance features inside Linear for issue tracking workflows.', 'Linear''s AI features help teams draft, search and triage product work inside Linear.', 'https://linear.app', 'published', 'Paid', 'Included in Linear plans', false, false, false, ARRAY['project-management', 'issues', 'linear']::text[], ARRAY['Native PM workflow']::text[], ARRAY['Tied to Linear product']::text[], ARRAY['Product teams']::text[], current_date from publishers p where p.name = 'Linear' on conflict (slug) do nothing;
commit;
